-- ==============================================================================
-- Migration 008: MedStore Merchandise Schema & Storage
-- Tables: medstore_products, storage bucket medstore
-- Official TANC Catalog Seed: 238 items (https://tanc.co.za/)
-- ==============================================================================

-- 1. Products Table
CREATE TABLE IF NOT EXISTS medstore_products (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  collection     TEXT NOT NULL CHECK (collection IN ('jackets', 'scrubs', 'pants', 'sets', 'coats', 'accessories')),
  price_zar      NUMERIC NOT NULL DEFAULT 0,
  price_usd      NUMERIC NOT NULL DEFAULT 0,
  rating         NUMERIC DEFAULT 4.9,
  reviews_count  INT DEFAULT 120,
  badge          TEXT,
  fabric_tech    TEXT,
  image_url      TEXT,
  image_urls     JSONB DEFAULT '[]'::jsonb,
  image_icon     TEXT DEFAULT '🛍️',
  description    TEXT DEFAULT '',
  colors         JSONB DEFAULT '[]'::jsonb,
  sizes          JSONB DEFAULT '[]'::jsonb,
  specs          JSONB DEFAULT '[]'::jsonb,
  display_order  INT DEFAULT 0,
  is_active      BOOLEAN DEFAULT true,
  created_at     TIMESTAMPTZ DEFAULT now(),
  updated_at     TIMESTAMPTZ DEFAULT now()
);

-- 2. Enable RLS
ALTER TABLE medstore_products ENABLE ROW LEVEL SECURITY;

-- 3. RLS Policies
DROP POLICY IF EXISTS "MedStore products readable by all" ON medstore_products;
CREATE POLICY "MedStore products readable by all"
  ON medstore_products FOR SELECT
  USING (is_active = true);

DROP POLICY IF EXISTS "Admins can insert products" ON medstore_products;
CREATE POLICY "Admins can insert products"
  ON medstore_products FOR INSERT
  WITH CHECK (
    auth.uid() IN (SELECT user_id FROM student_profiles WHERE is_admin = true)
    OR auth.role() = 'service_role'
  );

DROP POLICY IF EXISTS "Admins can update products" ON medstore_products;
CREATE POLICY "Admins can update products"
  ON medstore_products FOR UPDATE
  USING (
    auth.uid() IN (SELECT user_id FROM student_profiles WHERE is_admin = true)
    OR auth.role() = 'service_role'
  );

DROP POLICY IF EXISTS "Admins can delete products" ON medstore_products;
CREATE POLICY "Admins can delete products"
  ON medstore_products FOR DELETE
  USING (
    auth.uid() IN (SELECT user_id FROM student_profiles WHERE is_admin = true)
    OR auth.role() = 'service_role'
  );

-- 4. Create Storage Bucket for Merchandise Pictures
INSERT INTO storage.buckets (id, name, public)
VALUES ('medstore', 'medstore', true)
ON CONFLICT (id) DO UPDATE SET public = true;

-- Storage RLS Policies
DROP POLICY IF EXISTS "Public can view medstore images" ON storage.objects;
CREATE POLICY "Public can view medstore images"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'medstore');

DROP POLICY IF EXISTS "Admins can upload medstore images" ON storage.objects;
CREATE POLICY "Admins can upload medstore images"
  ON storage.objects FOR INSERT
  WITH CHECK (
    bucket_id = 'medstore' AND (
      auth.uid() IN (SELECT user_id FROM student_profiles WHERE is_admin = true)
      OR auth.role() = 'service_role'
    )
  );

DROP POLICY IF EXISTS "Admins can delete medstore images" ON storage.objects;
CREATE POLICY "Admins can delete medstore images"
  ON storage.objects FOR DELETE
  USING (
    bucket_id = 'medstore' AND (
      auth.uid() IN (SELECT user_id FROM student_profiles WHERE is_admin = true)
      OR auth.role() = 'service_role'
    )
  );

-- ==============================================================================
-- 5. Seed Catalog with Official TANC Merchandise
-- ==============================================================================

